//! The Frame methods a Plot uses to choose tick spacing and to split and
//! abbreviate axis labels (`gap`, `centre`, `abbrev`, `fields`), checked
//! against the C library.
//!
//! `plot_frame_methods_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/plot_frame_methods_probe.c`, which calls the
//! protected `astGap`, `astCentre`, `astAbbrev` and `astFields` on each Frame
//! that `frame` below builds from the same id.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "plot_frame_methods_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{
    BasicFrameBuilder, CmpFrame, FluxFrame, Frame, FrameRef, FrameSet, SkyFrame, SkySystem,
    SpecFluxFrame, SpecFrame, TimeFrame, TimeSystem, pick_axes,
};
use starlink_ast::mappings::UnitMap;
use starlink_ast::regions::BoxRegionBuilder;

/// The Frame a probe case id names, built as the probe builds it.
fn frame(id: &str) -> Box<dyn Frame> {
    match id {
        "basic2" => Box::new(BasicFrameBuilder::new(2).build().unwrap()),
        "sky" => Box::new(SkyFrame::unset_system()),
        "sky_perm" => {
            let mut f = SkyFrame::unset_system();
            f.perm_axes(&[2, 1]).unwrap();
            Box::new(f)
        }
        "sky_fmt" => {
            let mut f = SkyFrame::unset_system();
            f.set_format_str(1, "hms.2").unwrap();
            f.set_format_str(2, "dms.1").unwrap();
            Box::new(f)
        }
        "sky_digits" => {
            let mut f = SkyFrame::unset_system();
            f.set_digits(10).unwrap();
            Box::new(f)
        }
        "sky_axdigits" => {
            let mut f = SkyFrame::unset_system();
            f.set_axis_digits(1, 3).unwrap();
            Box::new(f)
        }
        "sky_gal" => {
            let mut f = SkyFrame::unset_system();
            f.set_system(SkySystem::Galactic);
            Box::new(f)
        }
        "time" => Box::new(TimeFrame::unset_system()),
        id if id.starts_with("time_") => Box::new(time_frame(id)),
        "cmp_sky_time" | "cmp_perm" => {
            let mut f = CmpFrame::new(
                Box::new(SkyFrame::unset_system()),
                Box::new(time_frame("time_iso")),
            );
            f.set_digits(10).unwrap();
            if id == "cmp_perm" {
                f.perm_axes(&[3, 1, 2]).unwrap();
            }
            Box::new(f)
        }
        "specflux" => Box::new(SpecFluxFrame::new(
            SpecFrame::unset_system(),
            FluxFrame::unset_system(),
        )),
        "frameset_sky" => {
            let mut fs = FrameSet::new(Box::new(BasicFrameBuilder::new(2).build().unwrap()));
            fs.add_frame(FrameRef::Base, Box::new(UnitMap::new(2)), frame("sky_fmt"))
                .unwrap();
            Box::new(fs)
        }
        "box_time_iso" => Box::new(
            BoxRegionBuilder::from_bounds(time_frame("time_iso"), &[56000.0], &[56001.0])
                .unwrap()
                .build()
                .unwrap(),
        ),
        "box_sky" => Box::new(
            BoxRegionBuilder::from_bounds(SkyFrame::unset_system(), &[0.0, 0.0], &[0.1, 0.1])
                .unwrap()
                .build()
                .unwrap(),
        ),
        "basic_skyaxis_ra" => pick_axes(&SkyFrame::unset_system(), &[1]).unwrap().0,
        "basic_skyaxis_dec" => pick_axes(&SkyFrame::unset_system(), &[2]).unwrap().0,
        _ => panic!("unknown frame id {id}"),
    }
}

/// A TimeFrame the probe builds with a date Format.
fn time_frame(id: &str) -> TimeFrame {
    let id = match id {
        "cmp_sky_time" | "cmp_perm" | "box_time_iso" => "time_iso",
        id => id,
    };
    let mut f = TimeFrame::unset_system();
    match id {
        "time_iso" => f.set_format_str(1, "iso.0").unwrap(),
        "time_iso2" => f.set_format_str(1, "iso.2").unwrap(),
        "time_isodate" => f.set_format_str(1, "iso").unwrap(),
        "time_jd_iso" => {
            f.set_system(TimeSystem::Jd).unwrap();
            f.set_unit(1, "d").unwrap();
            f.set_format_str(1, "iso.0").unwrap();
        }
        "time_origin_iso" => {
            f.set_time_origin(56000.0);
            f.set_format_str(1, "iso.0").unwrap();
        }
        "time_unit_h_iso" => {
            f.set_unit(1, "h").unwrap();
            f.set_format_str(1, "iso.0").unwrap();
        }
        _ => panic!("unknown frame id {id}"),
    }
    f
}

/// Frames whose `gap` C and the port measure from the current time, each
/// reading the clock when it runs.
///
/// A TimeFrame with a date Format finds the gap by converting the current
/// time and the current time plus the gap to MJD and back, so the result
/// carries the rounding of values the size of the current time, which
/// differs between the moment the probe ran and the moment the test runs.
/// These cases are compared within 8 ULP of the current time on the axis,
/// far below the one-second difference between neighboring steps of the
/// gap ladder; the division count is still compared exactly.
const CLOCK_GAP_LICENSED: &[(&str, usize)] = &[
    ("time_iso", 1),
    ("time_iso2", 1),
    ("time_isodate", 1),
    ("time_jd_iso", 1),
    ("time_origin_iso", 1),
    ("time_unit_h_iso", 1),
    ("cmp_sky_time", 3),
    ("cmp_perm", 1),
    ("box_time_iso", 1),
];

fn gap_eq(id: &str, axis: usize, got: f64, want: f64) -> bool {
    if CLOCK_GAP_LICENSED.contains(&(id, axis)) {
        let now = time_frame(id).current_time().unwrap();
        (got - want).abs() <= 8.0 * now.abs() * f64::EPSILON
    } else {
        crate::common::c_value_eq(got, want)
    }
}

#[test]
fn gap_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(id, axis, gap, want, want_ntick) in cases::GAP_CASES {
        let (got, ntick) = frame(id).gap(axis, gap).unwrap();
        if !gap_eq(id, axis, got, want) || ntick != want_ntick {
            failures.push(format!(
                "{id} axis {axis} gap {gap}: got ({got}, {ntick:?}), C gives ({want}, {want_ntick:?})"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn gap_of_zero_leaves_ntick_unset() {
    let f = BasicFrameBuilder::new(2).build().unwrap();
    assert_eq!(f.gap(1, 0.0).unwrap(), (0.0, None));
}

/// `centre` cases where the port differs from C by decision, as `(frame
/// id, axis, value, gap, the port's value, reason)`.
/// Where C sets the first field that differs between the dates a gap
/// either side of the value to zero, the port starts a day at 1, and takes
/// the start of a month or year inside the window (quirk "TimeFrame
/// `Centre` zeroes a calendar field that has no zero").
const CENTRE_EXCLUDED: &[(&str, usize, f64, f64, f64, &str)] = &[
    ("time_iso", 1, 56000.37, 1.0, 55987.0, DAY),
    ("time_iso", 1, 56000.37, -1.0, 55987.0, DAY),
    ("time_isodate", 1, 56000.37, 3.0, 55987.0, DAY),
    ("time_jd_iso", 1, 2456000.87, 1.0, 2455987.5, DAY),
    ("time_origin_iso", 1, 0.37, 1.0, -13.0, DAY),
    ("box_time_iso", 1, 56000.37, 1.0, 55987.0, DAY),
    ("cmp_perm", 1, 56000.37, 1.0, 55987.0, DAY),
    ("time_iso", 1, 56000.37, 30.0, 56018.0, MONTH),
    ("time_iso", 1, 56292.5, 2.0, 56293.0, YEAR),
];

const DAY: &str = "the day differs: the port gives the first of the month, C sets the day \
                   to 0, the last day of the previous month; the ticks are the same";
const MONTH: &str = "the month differs: the port gives the start of the month inside the \
                     window, C sets it to 0, no date, and falls back to a multiple of the gap";
const YEAR: &str = "the year differs: the port gives the start of the year inside the \
                    window, C sets it to 0, no date, and falls back to a multiple of the gap";

/// The port's own value for a `centre` case in [`CENTRE_EXCLUDED`].
fn centre_excluded(id: &str, axis: usize, value: f64, gap: f64) -> Option<f64> {
    CENTRE_EXCLUDED
        .iter()
        .find(|&&(i, a, v, g, _, _)| (i, a, v, g) == (id, axis, value, gap))
        .map(|c| c.4)
}

/// Each excluded case is still in the corpus, so the list cannot hold a
/// case that has gone; `centre_matches_the_c_library` fails for one that
/// has started to agree with C.
#[test]
fn centre_excluded_cases_are_in_the_corpus() {
    for &(id, axis, value, gap, _, reason) in CENTRE_EXCLUDED {
        assert!(
            cases::CENTRE_CASES
                .iter()
                .any(|&(i, a, v, g, _)| (i, a, v, g) == (id, axis, value, gap)),
            "{id} axis {axis} value {value} gap {gap} ({reason}) is not in the corpus"
        );
    }
}

#[test]
fn centre_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(id, axis, value, gap, want) in cases::CENTRE_CASES {
        let got = frame(id).centre(axis, value, gap).unwrap();
        if let Some(port) = centre_excluded(id, axis, value, gap) {
            if got != port || got == want {
                failures.push(format!(
                    "{id} axis {axis} value {value} gap {gap}: got {got}, the port gives \
                     {port} and C {want}; update CENTRE_EXCLUDED"
                ));
            }
        } else if !crate::common::c_value_eq(got, want) {
            failures.push(format!(
                "{id} axis {axis} value {value} gap {gap}: got {got}, C gives {want}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn abbrev_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(id, axis, fmt, str1, str2, want) in cases::ABBREV_CASES {
        let got = frame(id).abbrev(axis, fmt, str1, str2).unwrap();
        if got != want {
            failures.push(format!(
                "{id} axis {axis} {fmt:?} {str1:?} {str2:?}: got {got}, C gives {want}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// `fields` cases where the port differs from C, as `(frame id, axis, fmt,
/// text, maxfld, reason)`.
const FIELDS_EXCLUDED: &[(&str, usize, &str, &str, usize, &str)] = &[];

fn fields_excluded(id: &str, axis: usize, fmt: &str, text: &str, maxfld: usize) -> bool {
    FIELDS_EXCLUDED
        .iter()
        .any(|&(i, a, f, t, m, _)| (i, a, f, t, m) == (id, axis, fmt, text, maxfld))
}

#[test]
fn fields_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(id, axis, fmt, text, maxfld, want, want_value) in cases::FIELDS_CASES {
        if fields_excluded(id, axis, fmt, text, maxfld) {
            continue;
        }
        let got = frame(id).fields(axis, fmt, text, maxfld).unwrap();
        let spans: Vec<(usize, usize)> = got.fields.iter().map(|r| (r.start, r.len())).collect();
        if spans != want || !crate::common::c_value_eq(got.value, want_value) {
            failures.push(format!(
                "{id} axis {axis} {fmt:?} {text:?} max {maxfld}: got {spans:?} {}, C gives {want:?} {want_value}",
                got.value
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Each excluded case is still in the corpus and still differs from C, so
/// the list cannot hold a case that has started to agree or has gone.
#[test]
fn fields_excluded_cases_still_differ_from_c() {
    for &(id, axis, fmt, text, maxfld, reason) in FIELDS_EXCLUDED {
        let case = cases::FIELDS_CASES
            .iter()
            .find(|c| (c.0, c.1, c.2, c.3, c.4) == (id, axis, fmt, text, maxfld))
            .unwrap_or_else(|| panic!("excluded case {id} {text:?} is not in the corpus"));
        let got = frame(id).fields(axis, fmt, text, maxfld).unwrap();
        let spans: Vec<(usize, usize)> = got.fields.iter().map(|r| (r.start, r.len())).collect();
        assert_ne!(
            spans, case.5,
            "{id} {text:?} now matches C; remove it ({reason})"
        );
    }
}

#[test]
fn fields_with_leading_spaces_end_at_the_last_non_blank() {
    let f = BasicFrameBuilder::new(1).build().unwrap();
    let split = f.fields(1, "%g", "  -7 ", 20).unwrap();
    assert_eq!(split.fields, vec![2..4]);
    assert_eq!(split.value, -7.0);
}

/// A sky value missing a separator its Format names has no fields. C
/// dereferences a null pointer here, so there is no C case to compare with.
#[test]
fn sky_fields_without_a_named_separator_find_none() {
    let f = SkyFrame::unset_system();
    let split = f.fields(1, "hms", "12:34", 3).unwrap();
    assert!(split.fields.is_empty());
    assert_eq!(split.value, starlink_ast::constants::BAD_VALUE);
    assert_eq!(f.abbrev(1, "hms", Some("12"), "12:34:56").unwrap(), 0);
}

/// A TimeFrame's date centre across a month end is the start of the next
/// month, the calendar boundary inside the window.
#[test]
fn time_centre_across_a_month_is_the_start_of_the_next_month() {
    let f = time_frame("time_iso");
    assert_eq!(f.centre(1, 56000.37, 30.0).unwrap(), 56018.0);
}

/// A Region's `fields` reaches its Frame's Axis object, as C's does, so a
/// Region on a TimeFrame splits a date as a plain axis would, finding
/// nothing, where the TimeFrame itself reads it.
#[test]
fn region_fields_bypass_timeframe_date_splitting() {
    let date = "2012-03-14 08:52:48";
    let region = frame("box_time_iso");
    let plain = BasicFrameBuilder::new(1).build().unwrap();
    let via_region = region.fields(1, "iso.0", date, 20).unwrap();
    assert_eq!(via_region, plain.fields(1, "iso.0", date, 20).unwrap());
    let direct = time_frame("time_iso").fields(1, "iso.0", date, 20).unwrap();
    assert_ne!(via_region.value, direct.value);
}

/// A TimeFrame's date centre of a bad value, which formats as `<bad>` with
/// no numeric field to compare, is the value itself, as in C.
#[test]
fn time_centre_of_a_bad_value_is_the_value() {
    let bad = starlink_ast::constants::BAD_VALUE;
    assert_eq!(time_frame("time_iso").centre(1, bad, 1.0).unwrap(), bad);
}

/// A gap that is not finite, or so small that its power of ten underflows,
/// cannot be made nice: C converts a NaN or infinite ratio to `int` there,
/// which is undefined, and the port reports a bad parameter.
#[test]
fn gap_that_cannot_be_made_nice_is_an_error() {
    use starlink_ast::error::ErrorCode;
    let plain = frame("basic2");
    for gap in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY, 5e-324, 1e-323] {
        assert_eq!(
            plain.gap(1, gap).unwrap_err().code(),
            ErrorCode::Bdpar,
            "gap {gap}"
        );
    }
    let time = time_frame("time_iso");
    assert_eq!(
        time.gap(1, f64::INFINITY).unwrap_err().code(),
        ErrorCode::Bdpar
    );
}

/// The offsets of the `-` characters in `text`.
fn hyphens(text: &str) -> Vec<usize> {
    text.match_indices('-').map(|(i, _)| i).collect()
}

/// A plain axis's minus signs are those its conversion writes, the value's
/// and its exponent's, and not a hyphen in the Format's own text.
#[test]
fn minus_signs_of_a_plain_axis_are_its_conversions() {
    let mut f = BasicFrameBuilder::new(2).build().unwrap();
    let fmt = f.format_str(1).unwrap();
    let text = f.format(1, -1.5e-15).unwrap();
    assert_eq!(hyphens(&text).len(), 2, "{text}");
    assert_eq!(f.minus_signs(1, &fmt, &text).unwrap(), hyphens(&text));
    f.set_format_str(1, "x-%g-y").unwrap();
    let text = f.format(1, -2.0).unwrap();
    assert_eq!(text, "x--2-y");
    assert_eq!(f.minus_signs(1, "x-%g-y", &text).unwrap(), vec![2]);
    let text = f.format(1, 2.0).unwrap();
    assert!(f.minus_signs(1, "x-%g-y", &text).unwrap().is_empty());
}

/// A sky axis writes its sign first, and nowhere else.
#[test]
fn minus_signs_of_a_sky_axis_are_its_leading_sign() {
    let f = frame("sky");
    let fmt = f.format_str(2).unwrap();
    let text = f.format(2, -0.001).unwrap();
    assert!(text.starts_with('-'), "{text}");
    assert_eq!(f.minus_signs(2, &fmt, &text).unwrap(), vec![0]);
    let text = f.format(2, 0.001).unwrap();
    assert!(f.minus_signs(2, &fmt, &text).unwrap().is_empty());
}

/// The hyphens of a date are not minus signs, through a TimeFrame and
/// through a CmpFrame holding one.
#[test]
fn minus_signs_of_a_date_are_none() {
    let f = time_frame("time_iso");
    let fmt = f.format_str(1).unwrap();
    let text = f.format(1, 60000.0).unwrap();
    assert!(text.contains('-'), "{text}");
    assert!(f.minus_signs(1, &fmt, &text).unwrap().is_empty());
    let c = frame("cmp_sky_time");
    let n = c.naxes();
    let fmt = c.format_str(n).unwrap();
    let text = c.format(n, 60000.0).unwrap();
    assert!(text.contains('-'), "{text}");
    assert!(c.minus_signs(n, &fmt, &text).unwrap().is_empty());
}
